import { build } from 'esbuild'
import { writeFile } from 'node:fs/promises'

// Bundle the application's actual generator, not a second PDF implementation.
const result = await build({
  entryPoints: ['src/services/pdf/pdfGenerator.ts'], bundle: true,
  platform: 'browser', format: 'iife', globalName: 'LoftDeskNativePdf',
  target: 'chrome138', minify: true, write: false,
})
await writeFile('netlify/functions/shared/native-pdf-browser.cjs',
  '// Generated by scripts/build-native-pdf-browser.mjs. Do not edit.\nmodule.exports = ' +
  JSON.stringify(result.outputFiles[0].text) + '\n')
